import React, { useState, useEffect } from "react";
import Navbar from "./Navbar";
import Footer from "./Footer";
import { Link } from 'react-router-dom';

function DashboardBooks() {
  const [book, setBook] = useState({ title: "", para: "", price: "", pic: "" });
  const [books, setBooks] = useState([]);

  // Load books from backend
  useEffect(() => {
    fetch("http://localhost:5009/books")
      .then((res) => res.json())
      .then((data) => setBooks(data))
      .catch((err) => console.error("Error fetching books:", err));
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!book.title || !book.price) return;

     // convert price to number
    const bookToSend = { ...book, price: Number(book.price) };

    console.log("Posting book:", JSON.stringify(bookToSend));


    try {
      const res = await fetch("http://localhost:5009/books", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(bookToSend),
      });

      if (res.ok) {
        const newBook = await res.json();
        setBooks([...books, newBook]); // add to UI
        setBook({ title: "", para: "", price: "", pic: "" });
      } else {
        console.error("Failed to add book");
      }
    } catch (err) {
      console.error("Error:", err);
    }
  };

  return (
    <>
      <Navbar />
      <div className="KO">
        <h1>My Dashboard</h1>
        <div className="flex justify-center gap-8 bg-white shadow-md py-4 mb-8">
          <Link to="/Dashboard" className="text-gray-700 hover:text-indigo-600 font-lg">Overview</Link>
          <Link to="/DashboardBooks" className="text-indigo-600 font-lg">Books</Link>
          <Link to="/DashboardSales" className="text-gray-700 hover:text-indigo-600 font-lg">Sales</Link>
        </div>

        <div className="KO2">
          <div className="max-w-6xl mx-auto px-6">
            {/* Add Book Form */}
            <div className="bg-white p-8 rounded-2xl shadow-md mb-10">
              <h3 className="text-2xl font-semibold mb-6">Add a New Book</h3>
              <form onSubmit={handleSubmit} className="space-y-4">
                <input type="text" placeholder="Book Title" value={book.title}
                  onChange={(e) => setBook({ ...book, title: e.target.value })} className="w-full border rounded-xl px-4 py-2" /><br/>
                <textarea placeholder="Description" value={book.para}
                  onChange={(e) => setBook({ ...book, para: e.target.value })} className="w-full border rounded-xl px-4 py-2" /><br/>
                <input type="number" placeholder="Price" value={book.price}
                  onChange={(e) => setBook({ ...book, price: e.target.value })} className="w-full border rounded-xl px-4 py-2" /><br/>
                <input type="text" placeholder="Image URL" value={book.pic}
                  onChange={(e) => setBook({ ...book, pic: e.target.value })} className="w-full border rounded-xl px-4 py-2" /><br/>
                <button type="submit" className="w-full bg-indigo-600 text-white py-2 rounded-xl hover:bg-indigo-700">
                  Post Book
                </button>
              </form>
            </div>

            {/* Books Collection */}
            <div className="Jobby">
              <h3 className="text-2xl font-semibold mb-4">Books Collection</h3>
              {books.length === 0 ? (
                <h1 className="text-gray-600">No books added yet.</h1>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  {books.map((b) => (
                    <div key={b._id} className="bg-white rounded-2xl shadow-md p-4 flex flex-col">
                      {b.pic && <img src={b.pic} alt={b.title} className="rounded-xl mb-4 h-40 object-cover" />}
                      <h4 className="text-lg font-bold">{b.title}</h4>
                      <p className="text-gray-600 flex-1">{b.para}</p>
                      <span className="mt-2 font-semibold text-indigo-600">${b.price}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div> 
      </div>
      <Footer />
    </>
  );
}

export default DashboardBooks;
